mapper.update:
update fly_form
form_code=#{formCode}, form_name=#{formName}, audit=#{audit}, submit_limit=#{submitLimit}, need_captcha=#{needCaptcha}, success_tip=#{successTip}, notify_email=#{notifyEmail}, status=#{status},
where id=#{id}

mapper.select:
select count(1) from fly_form
where form_code=#{formCode}
and id <> #{id}

select  from fly_form

order by id desc
limit #{offset},#{rows}

mapper.update:
update fly_form_field
field_code=#{fieldCode}, field_name=#{fieldName}, field_type=#{fieldType}, required=#{required}, default_value=#{defaultValue}, placeholder=#{placeholder}, options=#{options}, sort=#{sort},
where id=#{id}

mapper.select:
select  from fly_form_field
where form_id=#{formId}
order by sort asc, id asc

select 
from fly_form_data d left join fly_form f on f.id = d.form_id
where d.id=#{id}
